package com.bank.state;

import java.util.logging.Logger;

interface LoanState {
    void approve(LoanApplication app);
    void disburse(LoanApplication app);
    String name();
}

class UnderReview implements LoanState {
    public void approve(LoanApplication app) { app.setState(new Approved()); app.log("Approved"); }
    public void disburse(LoanApplication app) { app.log("Cannot disburse before approval"); }
    public String name() { return "UNDER_REVIEW"; }
}
class Approved implements LoanState {
    public void approve(LoanApplication app) { app.log("Already approved"); }
    public void disburse(LoanApplication app) { app.setState(new Disbursed()); app.log("Disbursed"); }
    public String name() { return "APPROVED"; }
}
class Disbursed implements LoanState {
    public void approve(LoanApplication app) { app.log("Loan already disbursed"); }
    public void disburse(LoanApplication app) { app.log("Loan already disbursed"); }
    public String name() { return "DISBURSED"; }
}

class LoanApplication {
    private static final Logger logger = Logger.getLogger("LOAN");
    private LoanState state = new UnderReview();   // context holds current state
    void setState(LoanState s) { this.state = s; }
    void approve() { state.approve(this); }         // delegate to state
    void disburse() { state.disburse(this); }
    void log(String msg) { logger.info(state.name() + ": " + msg); }
}

public class StateDemo {
    public static void main(String[] args) {
        LoanApplication rajeshLoan = new LoanApplication();
        rajeshLoan.disburse(); // illegal now: under review
        rajeshLoan.approve();  // → approved
        rajeshLoan.disburse(); // → disbursed
    }
}
